{"content": "1|/// Command handler for MQTT-received commands from Home Assistant or other sources.
2|///
3|/// Handles Teams-for-Linux compatible commands:
4|/// - `toggle-mute` — toggle microphone mute state
5|/// - `toggle-video` — toggle camera on/off
6|/// - `toggle-hand-raise` — toggle hand raise in meetings
7|/// - `start-screen-share` / `stop-screen-share` — screen sharing control
8|/// - `get-calendar` — fetch calendar events (non-shortcut action)
9|///
10|/// Security: validates incoming commands against an allowed-actions whitelist
11|/// (mirrors the Electron app's `allowedActions` check in mqtt/index.js).
12|
13|use tracing::{debug, warn};
14|
15|/// Allowed MQTT command actions (mirrors Electron's `allowedActions`).
16|pub const ALLOWED_ACTIONS: &[&str] = &[
17|    "toggle-mute",
18|    "toggle-video",
19|    "toggle-hand-raise",
20|    "start-screen-share",
21|    "stop-screen-share",
22|    "get-calendar",
23|];
24|
25|/// Handler for incoming MQTT commands.
26|pub struct CommandHandler {
27|    /// Callback for toggle-mute
28|    on_toggle_mute: Option<tokio::sync::Mutex<Option<Box<dyn Fn() -> tokio::task::JoinHandle<()> + Send>>>>,
29|    /// Callback for toggle-video
30|    on_toggle_video: Option<tokio::sync::Mutex<Option<Box<dyn Fn() -> tokio::task::JoinHandle<()> + Send>>>>,
31|    /// Callback for toggle-hand-raise
32|    on_toggle_hand_raise: Option<tokio::sync::Mutex<Option<Box<dyn Fn() -> tokio::task::JoinHandle<()> + Send>>>>,
33|    /// Callback for start screen share
34|    on_start_screen_share: Option<tokio::sync::Mutex<Option<Box<dyn Fn() -> tokio::task::JoinHandle<()> + Send>>>>,
35|    /// Callback for stop screen share
36|    on_stop_screen_share: Option<tokio::sync::Mutex<Option<Box<dyn Fn() -> tokio::task::JoinHandle<()> + Send>>>>,
37|    /// Callback for get-calendar
38|    on_get_calendar: Option<tokio::sync::Mutex<Option<Box<dyn Fn() -> tokio::task::JoinHandle<()> + Send>>>>,
39|}
40|
41|impl CommandHandler {
42|    /// Create a new command handler with no callbacks registered.
43|    pub fn new() -> Self {
44|        Self {
45|            on_toggle_mute: None,
46|            on_toggle_video: None,
47|            on_toggle_hand_raise: None,
48|            on_start_screen_share: None,
49|            on_stop_screen_share: None,
50|            on_get_calendar: None,
51|        }
52|    }
53|
54|    /// Register a callback for toggle-mute commands.
55|    pub fn on_toggle_mute<F>(&mut self, callback: F)
56|    where
57|        F: Fn() -> tokio::task::JoinHandle<()> + Send + 'static,
58|    {
59|        self.on_toggle_mute = Some(tokio::sync::Mutex::new(Some(Box::new(callback))));
60|    }
61|
62|    /// Register a callback for toggle-video commands.
63|    pub fn on_toggle_video<F>(&mut self, callback: F)
64|    where
65|        F: Fn() -> tokio::task::JoinHandle<()> + Send + 'static,
66|    {
67|        self.on_toggle_video = Some(tokio::sync::Mutex::new(Some(Box::new(callback))));
68|    }
69|
70|    /// Register a callback for toggle-hand-raise commands.
71|    pub fn on_toggle_hand_raise<F>(&mut self, callback: F)
72|    where
73|        F: Fn() -> tokio::task::JoinHandle<()> + Send + 'static,
74|    {
75|        self.on_toggle_hand_raise = Some(tokio::sync::Mutex::new(Some(Box::new(callback))));
76|    }
77|
78|    /// Register a callback for start-screen-share commands.
79|    pub fn on_start_screen_share<F>(&mut self, callback: F)
80|    where
81|        F: Fn() -> tokio::task::JoinHandle<()> + Send + 'static,
82|    {
83|        self.on_start_screen_share = Some(tokio::sync::Mutex::new(Some(Box::new(callback))));
84|    }
85|
86|    /// Register a callback for stop-screen-share commands.
87|    pub fn on_stop_screen_share<F>(&mut self, callback: F)
88|    where
89|        F: Fn() -> tokio::task::JoinHandle<()> + Send + 'static,
90|    {
91|        self.on_stop_screen_share = Some(tokio::sync::Mutex::new(Some(Box::new(callback))));
92|    }
93|
94|    /// Register a callback for get-calendar commands.
95|    pub fn on_get_calendar<F>(&mut self, callback: F)
96|    where
97|        F: Fn() -> tokio::task::JoinHandle<()> + Send + 'static,
98|    {
99|        self.on_get_calendar = Some(tokio::sync::Mutex::new(Some(Box::new(callback))));
100|    }
101|
102|    /// Handle an incoming MQTT command.
103|    ///
104|    /// Validates the action against the allowed-actions whitelist before dispatching.
105|    /// Returns `Some(action)` if the command was handled, `None` if it was rejected
106|    /// or unknown.
107|    pub async fn handle(&self, action: &str, request_id: Option<String>) -> bool {
108|        // Whitelist validation (mirrors Electron's `allowedActions.includes()` check)
109|        if !ALLOWED_ACTIONS.contains(&action) {
110|            warn!(action, "Rejected MQTT command: action not in whitelist");
111|            return false;
112|        }
113|
114|        debug!(action, ?request_id, "Handling MQTT command");
115|
116|        match action {
117|            "toggle-mute" => {
118|                if let Some(tx) = &self.on_toggle_mute {
119|                    let guard = tx.lock().await;
120|                    if let Some(cb) = guard.as_ref() {
121|                        let _ = cb();
122|                    }
123|                }
124|            }
125|            "toggle-video" => {
126|                if let Some(tx) = &self.on_toggle_video {
127|                    let guard = tx.lock().await;
128|                    if let Some(cb) = guard.as_ref() {
129|                        let _ = cb();
130|                    }
131|                }
132|            }
133|            "toggle-hand-raise" => {
134|                if let Some(tx) = &self.on_toggle_hand_raise {
135|                    let guard = tx.lock().await;
136|                    if let Some(cb) = guard.as_ref() {
137|                        let _ = cb();
138|                    }
139|                }
140|            }
141|            "start-screen-share" => {
142|                if let Some(tx) = &self.on_start_screen_share {
143|                    let guard = tx.lock().await;
144|                    if let Some(cb) = guard.as_ref() {
145|                        let _ = cb();
146|                    }
147|                }
148|            }
149|            "stop-screen-share" => {
150|                if let Some(tx) = &self.on_stop_screen_share {
151|                    let guard = tx.lock().await;
152|                    if let Some(cb) = guard.as_ref() {
153|                        let _ = cb();
154|                    }
155|                }
156|            }
157|            "get-calendar" => {
158|                if let Some(tx) = &self.on_get_calendar {
159|                    let guard = tx.lock().await;
160|                    if let Some(cb) = guard.as_ref() {
161|                        let _ = cb();
162|                    }
163|                }
164|            }
165|            _ => {
166|                // Should not reach here due to whitelist check above, but handle defensively.
167|                warn!(action, "Unknown MQTT command received");
168|                return false;
169|            }
170|        }
171|
172|        true
173|    }
174|}
175|
176|impl Default for CommandHandler {
177|    fn default() -> Self {
178|        Self::new()
179|    }
180|}
181|
182|#[cfg(test)]
183|mod tests {
184|    use super::*;
185|
186|    #[test]
187|    fn test_command_handler_creation() {
188|        let handler = CommandHandler::new();
189|        assert!(handler.on_toggle_mute.is_none());
190|        assert!(handler.on_toggle_video.is_none());
191|        assert!(handler.on_get_calendar.is_none());
192|    }
193|
194|    #[test]
195|    fn test_default_command_handler() {
196|        let handler = CommandHandler::default();
197|        assert!(handler.on_toggle_mute.is_none());
198|    }
199|
200|    #[test]
201|    fn test_whitelist_contains_expected_actions() {
202|        assert!(ALLOWED_ACTIONS.contains(&"toggle-mute"));
203|        assert!(ALLOWED_ACTIONS.contains(&"toggle-video"));
204|        assert!(ALLOWED_ACTIONS.contains(&"toggle-hand-raise"));
205|        assert!(ALLOWED_ACTIONS.contains(&"start-screen-share"));
206|        assert!(ALLOWED_ACTIONS.contains(&"stop-screen-share"));
207|        assert!(ALLOWED_ACTIONS.contains(&"get-calendar"));
208|    }
209|
210|    #[test]
211|    fn test_whitelist_rejects_unknown_action() {
212|        assert!(!ALLOWED_ACTIONS.contains(&"unknown-action"));
213|        assert!(!ALLOWED_ACTIONS.contains(&"delete-meeting"));
214|        assert!(!ALLOWED_ACTIONS.contains(&""));
215|    }
216|}
