{"content": "1|/// MQTT integration for CrabJar host.
2|///
3|/// Provides a bidirectional MQTT client for Teams status publishing
4|/// and command reception. Mirrors the Teams-for-Linux MQTT integration:
5|/// - Status publishing: presence, call state, camera, mic, screen-sharing
6|/// - Command reception: toggle-mute, toggle-video, toggle-hand-raise
7|/// - Home Assistant auto-discovery
8|/// - Last Will and Testament (LWT) for connection state
9|/// - Automatic reconnection with backoff
10|
11|pub mod client;
12|pub mod config;
13|pub mod discovery;
14|pub mod handler;
15|
16|pub use client::MqttClient;
17|pub use client::MqttError;
18|pub use config::{MqttConfig, HomeAssistantConfig};
19|pub use discovery::HaDiscovery;
20|pub use handler::CommandHandler;
21|
22|/// Status codes matching Teams-for-Linux convention.
23|#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
24|#[serde(rename_all = "snake_case")]
25|pub enum PresenceStatus {
26|    Unknown = -1,
27|    Available = 1,
28|    Busy = 2,
29|    DoNotDisturb = 3,
30|    Away = 4,
31|    BeRightBack = 5,
32|}
33|
34|impl PresenceStatus {
35|    pub fn as_str(&self) -> &'static str {
36|        match self {
37|            PresenceStatus::Unknown => "unknown",
38|            PresenceStatus::Available => "available",
39|            PresenceStatus::Busy => "busy",
40|            PresenceStatus::DoNotDisturb => "do_not_disturb",
41|            PresenceStatus::Away => "away",
42|            PresenceStatus::BeRightBack => "be_right_back",
43|        }
44|    }
45|
46|    pub fn from_code(code: i32) -> Self {
47|        match code {
48|            1 => PresenceStatus::Available,
49|            2 => PresenceStatus::Busy,
50|            3 => PresenceStatus::DoNotDisturb,
51|            4 => PresenceStatus::Away,
52|            5 => PresenceStatus::BeRightBack,
53|            _ => PresenceStatus::Unknown,
54|        }
55|    }
56|}
57|
58|/// Presence status update published to MQTT.
59|///
60|/// Includes deduplication support: `should_publish()` checks whether this
61|/// update differs from the last published status, mirroring the Electron
62|/// app's `lastPublishedStatus` check in mqtt/index.js.
63|#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
64|pub struct PresenceUpdate {
65|    pub status: String,
66|    pub status_code: i32,
67|    pub timestamp: String,
68|    pub client_id: String,
69|}
70|
71|impl PresenceUpdate {
72|    /// Check whether this update should be published.
73|    ///
74|    /// Returns `false` if `last_published_status` matches the current status,
75|    /// indicating a duplicate that should be skipped. Returns `true` if the
76|    /// status has changed or no previous status exists.
77|    pub fn should_publish(&self, last_published_status: Option<&str>) -> bool {
78|        match last_published_status {
79|            Some(prev) if prev == &self.status => false,
80|            _ => true,
81|        }
82|    }
83|}
84|
85|/// Media state for MQTT publishing.
86|#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
87|pub enum MediaState {
88|    Camera { enabled: bool },
89|    Microphone { state: String },
90|    InCall { in_call: bool },
91|    ScreenSharing { sharing: bool },
92|}
93|
94|/// MQTT event types for the event bus bridge.
95|#[derive(Debug, Clone)]
96|pub enum MqttEvent {
97|    Connected,
98|    Disconnected,
99|    StatusChanged(PresenceUpdate),
100|    MediaStateChanged(MediaState),
101|    CommandReceived { action: String, request_id: Option<String> },
102|}
103|
