107|
108|    fn make_update(status: &str) -> PresenceUpdate {
109|        PresenceUpdate {
110|            status: status.to_string(),
111|            status_code: 1,
112|            timestamp: "2026-01-01T00:00:00Z".into(),
113|            client_id: "test".into(),
114|        }
115|    }
116|
117|    #[test]
118|    fn test_dedup_no_previous() {
119|        let update = make_update("available");
120|        assert!(update.should_publish(None));
121|    }
122|
123|    #[test]
124|    fn test_dedup_different_status() {
125|        let update = make_update("busy");
126|        assert!(update.should_publish(Some("available")));
127|    }
